import json,collections,re
meds={}
for l in open('Medication.ndjson'):
    m=json.loads(l); meds[m['id']]=m
def mname(x):
    if 'medicationCodeableConcept' in x:
        return ' | '.join(c.get('code','')+'~'+c.get('display','') for c in x['medicationCodeableConcept'].get('coding',[]))
    r=x.get('medicationReference',{}).get('reference','')
    m=meds.get(r.split('/')[-1])
    if not m: return r
    return ' | '.join(c.get('code','')+'~'+c.get('display','') for c in m.get('code',{}).get('coding',[]))
mr=[json.loads(l) for l in open('MedicationRequest.ndjson')]
pat=re.compile(r'warfarin|coumadin|apixaban|eliquis|rivaroxaban|xarelto|dabigatran|pradaxa|edoxaban|savaysa|heparin|enoxaparin|lovenox|fondaparinux|argatroban|bivalirudin|dalteparin', re.I)
hits=[x for x in mr if pat.search(mname(x))]
print(len(hits))
c=collections.Counter(mname(x) for x in hits)
for k,v in c.most_common(): print(v,k)
"

