import json,collections,base64,re,os
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
docs=[json.loads(l) for l in open('DocumentReference.ndjson')]
notes=collections.defaultdict(list)
for d in docs:
    s=d.get('subject',{}).get('reference','').split('/')[-1]
    if s: notes[s].append(d)
ecgs=collections.defaultdict(list)
for e in json.load(open('ecgs.json'))['ecgs']: ecgs[e['patient']].append(e)

meds={}
for l in open('Medication.ndjson'):
    m=json.loads(l)
    nm=''
    for i in m.get('identifier',[]):
        if i['system'].endswith('medication-name'): nm=i['value']
    meds[m['id']]=nm
def mname(x):
    if 'medicationCodeableConcept' in x:
        return ' | '.join((c.get('display') or c.get('code','')) for c in x['medicationCodeableConcept'].get('coding',[]))
    r=x.get('medicationReference',{}).get('reference','')
    return meds.get(r.split('/')[-1], r)

DRUGS=re.compile(r'warfarin|coumadin|apixaban|eliquis|rivaroxaban|xarelto|dabigatran|pradaxa|edoxaban|savaysa|enoxaparin|lovenox|fondaparinux|argatroban|bivalirudin|dalteparin|citalopram|escitalopram|haloperidol|methadone|amiodarone|sotalol|dofetilide|heparin', re.I)
mrs=collections.defaultdict(list)
for l in open('MedicationRequest.ndjson'):
    x=json.loads(l)
    n=mname(x)
    if DRUGS.search(n):
        mrs[x['subject']['reference'].split('/')[-1]].append((x,n))

conds=collections.defaultdict(list)
for l in open('Condition.ndjson'):
    x=json.loads(l)
    conds[x['subject']['reference'].split('/')[-1]].append(x)

encs={}
for l in open('Encounter.ndjson'):
    x=json.loads(l); encs[x['id']]=x

LABS=re.compile(r'^(INR\(PT\)|INR|Potassium|Magnesium|Potassium, Whole Blood|Potassium \(serum\)|Magnesium|Potassium \(whole blood\))$')
obs=collections.defaultdict(list)
for l in open('Observation.ndjson'):
    x=json.loads(l)
    for cd in x.get('code',{}).get('coding',[]):
        d=cd.get('display') or ''
        if d in ('INR(PT)','INR','Potassium','Magnesium','Potassium (serum)','Magnesium','Potassium (whole blood)','Potassium, Whole Blood'):
