import numpy as np, wfdb, os, json
import scipy.signal as sg

FS=500
LEADS=['I','II','III','aVR','aVF','aVL','V1','V2','V3','V4','V5','V6']

def load(eid):
    r=wfdb.rdrecord(f'ecg/{eid}')
    sig=np.asarray(r.p_signal,dtype=float)  # n x 12
    names=list(r.sig_name)
    # fix NaNs
    for i in range(sig.shape[1]):
        col=sig[:,i]
        m=np.isnan(col)
        if m.all(): sig[:,i]=0
        elif m.any(): col[m]=np.interp(np.flatnonzero(m),np.flatnonzero(~m),col[~m])
    return sig,names,r

def bp(x,lo=0.5,hi=40.0):
    b,a=sg.butter(3,[lo/(FS/2),hi/(FS/2)],btype='band')
    return sg.filtfilt(b,a,x,axis=0)

def notch(x):
    b,a=sg.iirnotch(60/(FS/2),30)
    return sg.filtfilt(b,a,x,axis=0)

def detect_r(sig):
    import neurokit2 as nk
    # composite
    d=np.diff(sig,axis=0)
    comp=np.sqrt((d**2).sum(axis=1))
    comp=np.concatenate([[comp[0]],comp])
    best=None
    for lead in ['II','I','V2','V5']:
        i=LEADS.index(lead)
        try:
            _,info=nk.ecg_peaks(sig[:,i],sampling_rate=FS,method='neurokit')
            pk=info['ECG_R_Peaks']
        except Exception:
            continue
        if len(pk)>=4:
            rr=np.diff(pk)
            score=np.std(rr)/max(np.mean(rr),1)
            if best is None or len(pk)>len(best[0])*0.0+0 and best is None:
                best=(pk,lead)
            if best is not None and len(pk)>len(best[0]):
                pass
            if best is None: best=(pk,lead)
    # simpler: use composite energy detector
    return comp
