import sys,os; sys.path.insert(0,'/tmp'); os.chdir('/tmp')
from ecg2 import *
import numpy as np

def plot(M,a,lo,hi,leads,rows=15,step=4,marks=()):
    n=len(M); lo=max(0,lo); hi=min(n,hi)
    cols=list(range(lo,hi,step))
    for ln in leads:
        y=M[:,LEADS.index(ln)]
        m=np.max(np.abs(y[lo:hi])) or 1
        g=[[' ']*len(cols) for _ in range(rows)]
        for c,i in enumerate(cols):
            r=int(round((rows-1)/2 - y[i]/m*((rows-1)/2)))
            g[max(0,min(rows-1,r))][c]='*'
        for r in range(rows):
            print((ln.ljust(4)+'%5.2f'%m if r==0 else ' '*9)+''.join(g[r]))
    ax=[' ']*len(cols); lab=[' ']*len(cols)
    for c,i in enumerate(cols):
        t=(i-a)*2
        if t%100==0:
            ax[c]='+'; s=str(t)
            for k,ch in enumerate(s):
                if c+k<len(lab): lab[c+k]=ch
    print(' '*9+''.join(ax)); print(' '*9+''.join(lab))
    row=[' ']*len(cols)
    for name,idx in marks:
        c=(idx-lo)//step
        if 0<=c<len(cols): row[c]=name[0]
    print(' '*9+''.join(row)+'   '+' '.join('%s=%d'%(n_,(i-a)*2) for n_,i in marks))

def show(eid,leads=('I','II','aVF','V1','V2','V5'),pre=350,post=560,step=4):
    r,M,a,on,off,rp=analyze(eid)
    print('===',eid,{k:v for k,v in r.items() if k not in('rr_ms',)})
    print('RR:',r.get('rr_ms'))
    marks=[('N',on),('F',off)]
    if r.get('p_on_t') is not None: marks.append(('P',a+r['p_on_t']//2))
    if r.get('t_end_t') is not None: marks.append(('T',a+r['t_end_t']//2))
    plot(M,a,a-pre//2,a+post//2,leads,step=step,marks=marks)
if __name__=='__main__':
    for e in sys.argv[1:]: show(e)
