import numpy as np
def strip(eid,leads=('II','V1'),rows=17,step=10,secs=(0,10)):
    x=filt(load(eid)); rp=detect_r(x)
    print('===',eid,'RR',(np.diff(rp)*2).tolist())
    lo=int(secs[0]*FS); hi=int(secs[1]*FS)
